{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Across all four datasets, test a smaller, more recent causal interest contribution: 0.9*h_t + 0.1*m_t with half-life two. Preserve padding exclusion, causal masking, final-real-position inference, and all other model and training settings.",
      "edits": [
        {
          "find": "        weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 4.0)",
          "replace": "        weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 2.0)"
        },
        {
          "find": "        return (0.8 * out + 0.2 * mean) * real",
          "replace": "        return (0.9 * out + 0.1 * mean) * real"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_4\",",
          "replace": "            \"sequence_readout\": \"gru_0.9_causal_mean_0.1_half_life_2\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_4\":",
          "replace": "        if meta.get(\"sequence_readout\") != \"gru_0.9_causal_mean_0.1_half_life_2\":"
        }
      ]
    }
  ],
  "change_summary": "Reduce causal interest pooling to 10% with a two-interaction half-life and synchronize checkpoint metadata with the embedded predictor writer."
}
